[def:장비청구대사]($assets, $checks, $invoices) {
  $자산키 = from_entries($assets >> [table:each]{return [text($it.asset_id), true]})
  $점검키 = from_entries(unique($checks >> [table:each]{return text($it.asset_id)}) >> [table:each]{return [$it, true]})
  $정규 = enumerate($invoices) >> [table:each]{
    $r = $it[1]
    $aid = get($r, "asset_id", null)
    $id = $aid != null ? $aid : get($r, "machine", null)
    $iid = get($r, "invoice_id", null)
    return {ord:$it[0], raw:$r, invoice_id:$iid, key:$iid == null ? "" : text($iid), id:$id == null ? "" : text($id)}
  }
  $정렬 = sorted($정규, "key")
  $표시 = enumerate($정렬) >> [table:each]{
    $r = $it[1]
    $dup = $it[0] > 0 and $r.invoice_id != null and $정렬[$it[0] - 1].key == $r.key
    return {**$r, dup:$dup, matched:$r.id != "" and has($자산키, $r.id)}
  }
  $연결 = $표시 >> [table:filter]{where:($r)=> $r.matched}
  $고유 = $연결 >> [table:filter]{where:($r)=> not $r.dup} >> [table:each]{
    $v = has($it.raw, "amount") ? $it.raw.amount : get($it.raw, "fee", null)
    assert $v != null, "청구 금액 없음", {invoice_id:$it.invoice_id}
    return {id:$it.id, amt:number(replace(replace(strip(text($v)), "₩", ""), ",", ""))}
  }
  $합계 = $고유 >> [table:groupby]{by:"id", agg:{actual:["sum", "amt"]}}
  $중복 = $연결 >> [table:filter]{where:($r)=> $r.dup} >> [table:groupby]{by:"id", agg:{n:["count"]}}
  $합계표 = from_entries($합계.items >> [table:each]{return [$it.id, $it.actual]})
  $중복표 = from_entries($중복.items >> [table:each]{return [$it.id, $it.n]})
  $rows = $assets >> [table:each]{
    $k = text($it.asset_id)
    $act = get($합계표, $k, 0)
    return {asset_id:$it.asset_id, branch:$it.branch, expected_cost:$it.expected_cost, actual_cost:$act, difference:$act - $it.expected_cost, missing_check:not has($점검키, $k), duplicate_count:get($중복표, $k, 0)}
  }
  $unmatched = sorted($표시 >> [table:filter]{where:($r)=> not $r.matched}, "ord") >> [table:each]{return $it.raw}
  return {
    rows:$rows,
    unmatched:$unmatched,
    total_actual:sum($rows >> [table:each]{return $it.actual_cost}),
    duplicates:len($표시 >> [table:filter]{where:($r)=> $r.dup}),
    missing_checks:len($rows >> [table:filter]{where:($r)=> $r.missing_check}),
    mismatches:len($rows >> [table:filter]{where:($r)=> $r.difference != 0})
  }
}
[def:장비청구대사_파일]($assets_path, $checks_path, $invoices_path, $output_path) {
  $a = [self:read]{path:$assets_path}
  $c = [self:read]{path:$checks_path}
  $v = [self:read]{path:$invoices_path}
  $rep = [fn:장비청구대사]{assets:$a.data.items, checks:$c.data.items, invoices:$v.data.items}
  $w = [self:write]{path:$output_path, content:json($rep)}
  return {output:$output_path, write:$w, rows:len($rep.rows), unmatched:len($rep.unmatched), total_actual:$rep.total_actual, duplicates:$rep.duplicates, missing_checks:$rep.missing_checks, mismatches:$rep.mismatches}
}
